const Quiz=(()=>{const KEY='aboutMeQuizStateV5';function state(){try{return JSON.parse(localStorage.getItem(KEY))||{score:0,answers:[]}}catch{return{score:0,answers:[]}}}function save(s){localStorage.setItem(KEY,JSON.stringify(s))}function reset(){save({score:0,answers:[]})}function answer(ok,right,wrong){const s=state(),step=Number(document.body.dataset.step)||1,i=step-1;if(s.answers[i]!==undefined)return;s.answers[i]=!!ok;if(ok)s.score++;save(s);const f=document.getElementById('feedback');if(f){f.textContent=ok?right:wrong;f.className='feedback '+(ok?'success':'fail')}document.querySelectorAll('.answer').forEach(b=>b.disabled=true);const n=document.getElementById('next');if(n)n.hidden=false;if(ok)confetti()}function multipleChoice(o){document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>answer(b.dataset.correct==='true',o.right,o.wrong))}function textGate(o){const form=document.getElementById('form'),input=document.getElementById('answer');form.onsubmit=e=>{e.preventDefault();const v=input.value.trim().toLowerCase();if(!o.answers.includes(v)){const f=document.getElementById('feedback');f.textContent=o.wrong;f.className='feedback fail';return}input.disabled=true;form.querySelector('button').disabled=true;answer(true,o.right,o.wrong)}}function confetti(){const x=document.createElement('div');x.className='confetti';for(let i=0;i<30;i++){const s=document.createElement('i');s.textContent=['✦','★','◆','•'][i%4];s.style.left=Math.random()*100+'%';s.style.animationDelay=Math.random()*.3+'s';x.appendChild(s)}document.body.appendChild(x);setTimeout(()=>x.remove(),1400)}return{state,save,reset,answer,multipleChoice,textGate,confetti}})();
